import{_ as n,c as e,o as t,ag as r}from"./chunks/framework.Cycwnjj0.js";const s="/assets/coonfiguring-amazon-api.C2GBDqLx.webp",h=JSON.parse('{"title":"Configure Amazon API in AzonPress","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuring-amazon-api/configure-amazon-api.md","filePath":"guide/configuring-amazon-api/configure-amazon-api.md"}'),a={name:"guide/configuring-amazon-api/configure-amazon-api.md"};function i(g,o,u,c,p,l){return t(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="configure-amazon-api-in-azonpress" tabindex="-1">Configure Amazon API in AzonPress <a class="header-anchor" href="#configure-amazon-api-in-azonpress" aria-label="Permalink to &quot;Configure Amazon API in AzonPress&quot;">​</a></h1><p>To use the AzonPress plugin on your WordPress site, you need to configure the Amazon API in AzonPress from your WordPress Site. This article will guide you through the whole process.</p><h2 id="amazon-api-configuration-in-azonpress" tabindex="-1">Amazon API Configuration In AzonPress <a class="header-anchor" href="#amazon-api-configuration-in-azonpress" aria-label="Permalink to &quot;Amazon API Configuration In AzonPress&quot;">​</a></h2><p>To learn how to configure Amazon API in AzonPress, follow the steps in the screenshot below –</p><p><strong>Remember</strong>, before configuring Amazon API with AzonPress, you must create credentials for Amazon Product Advertising API. After <strong>creating Amazon API</strong> from your <strong>Amazon Site</strong> successfully, go to your <strong>WordPress Site</strong> and install the AzonPress plugin.</p><p>First, go to <strong>Settings</strong> from the <strong>WordPress Sidebar</strong> or <strong>AzonPress Navbar</strong>, and open the <strong>Amazon API</strong> settings option from the left sidebar.</p><p>Now, configure all the <strong>necessary credentials</strong> into the desired input fields that you have generated on your <strong>Amazon Associate Account</strong>.</p><p>Besides, the configuration fields, you will also get two more interesting settings. These are:</p><ul><li><strong>Amazon API Call Smart Caching:</strong> You will find an API Caching Time option; in that case, you can set caching time in minutes.</li><li><strong>Geo-Targeting Settings:</strong> There is another option named Geo-Target Type, where you can get three options to configure your account with the plugin.</li></ul><p>Once you are done, click on the <strong>Update</strong> button to save your <strong>Amazon API Configuration</strong> and your configuration will be complete successfully.</p><p><img src="'+s+'" alt="Configuring Amazon API"></p><p>This is how you can set up your API key and other relevant issues using the AzonPress plugin!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',14)])])}const A=n(a,[["render",i]]);export{h as __pageData,A as default};
